1	package com.cockpitbench.foundation.platform;
2	import android.os.*;import java.util.*;import java.util.concurrent.*;
3	public final class BinderConnectionSupervisor implements IBinder.DeathRecipient,AutoCloseable { public interface Observer{void onConnected(IBinder binder);void onDisconnected();}
4	 private final ScheduledExecutorService scheduler;private final Observer observer;private final long retryMillis;private IBinder binder;private boolean closed;
5	 public BinderConnectionSupervisor(ScheduledExecutorService s,Observer o,long retry){scheduler=Objects.requireNonNull(s);observer=Objects.requireNonNull(o);retryMillis=retry;if(retry<=0)throw new IllegalArgumentException("retry");}
6	 public synchronized void attach(IBinder value)throws RemoteException{if(closed)throw new IllegalStateException("closed");detach();binder=Objects.requireNonNull(value);binder.linkToDeath(this,0);observer.onConnected(binder);}
7	 public synchronized void detach(){if(binder!=null){binder.unlinkToDeath(this,0);binder=null;observer.onDisconnected();}}
8	 @Override public void binderDied(){synchronized(this){binder=null;}observer.onDisconnected();scheduler.schedule(()->{},retryMillis,TimeUnit.MILLISECONDS);}
9	 @Override public synchronized void close(){closed=true;detach();}}
