1	package com.cockpitbench.foundation.platform;
2	import android.os.*;import com.cockpitbench.foundation.api.ICockpitEventListener;
3	public final class CallbackRegistry implements AutoCloseable { private final RemoteCallbackList<ICockpitEventListener> callbacks=new RemoteCallbackList<>();
4	 public void add(ICockpitEventListener value){callbacks.register(value);}public void remove(ICockpitEventListener value){callbacks.unregister(value);}
5	 public void publish(String domain,String event,Bundle payload){int count=callbacks.beginBroadcast();try{for(int i=0;i<count;i++)try{callbacks.getBroadcastItem(i).onEvent(domain,event,payload);}catch(RemoteException ignored){}}finally{callbacks.finishBroadcast();}}
6	 @Override public void close(){callbacks.kill();}}
