1	package com.cockpitbench.foundation.storage;
2	import java.util.*;
3	public final class SnapshotStore { private final NavigableMap<Long,Map<String,String>> values=new TreeMap<>();private final int capacity;
4	 public SnapshotStore(int capacity){if(capacity<=0)throw new IllegalArgumentException("capacity");this.capacity=capacity;}
